"""Negation and exclusion detector (layer 15, MLP down-projection, one component).

What it does: the component goes negative on words that negate or exclude
something, and is near zero on almost every other token.

  * strongest (about -16): "non-", "without" and their translations
    ("ohne", "sans", "без", "senza", "zonder", "bez", "无", "無", "非", "regardless");
  * medium (about -6): plain negators and absence words ("not", "no", "none",
    "nothing", "fewer", "less", "low", "outside", "absence", "不", "没有", "未", "nicht", "не");
  * weak (about -3): other negation, lack and exclusion words ("never", "nor",
    "neither", "cannot", "lack", "avoid", "pas", "nie", "un-", "n't", "beyond",
    "except", "unless", "lower", "zero", "empty");
  * the word right after a strong or medium negator is pulled slightly negative (-2),
    since the negated phrase is also affected.

Everything else predicts 0 (the component's mean is about -0.1).
The lookup is on the token's own text, so it reads only the current and previous token.
"""

STRONG = {"non", "without", "ohne", "sans", "без", "senza", "zonder", "bez",
          "regardless", "无", "無", "非"}
MEDIUM = {"not", "no", "none", "nothing", "absence", "outside", "fewer", "less", "low",
          "不", "没", "没有", "未", "nobody", "nicht", "не", "kein", "keine"}
WEAK = {"never", "nor", "neither", "cannot", "lack", "avoid", "pas", "nie", "un", "'t",
        "’t", "beyond", "except", "unless", "lower", "zero", "empty"}

READS = ()


def word(token):
    return token.strip().lower().strip("-_")


def value_of(token):
    w = word(token)
    if w in STRONG:
        return -16.0
    if w in MEDIUM:
        return -6.0
    if w in WEAK:
        return -3.0
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    value = value_of(prefix.token_strings[-1])
    if t >= 1 and prefix.document_ids[-1] == prefix.document_ids[-2]:
        if value == 0.0 and value_of(prefix.token_strings[-2]) <= -6.0:
            value = -2.0
    return carry, value

"""Layer 15, MLP neuron 1423 (component p-82af68dd@100000/layers.15.mlp.down_proj:1423).

This component reads mainly MLP hidden unit 1423 of layer 15 (its input direction puts most
of its weight there; correlation about 0.64 with that unit's value). In plain terms it is
negative on the punctuation that comes just before a value in structured text:

- the colon that closes a JSON key, very strongly for the "name" key of a tool call
  ("name": "bash"), moderately for other keys;
- the opening quote of a JSON string value, just after such a colon;
- equals signs and colons in code and maths, and plus signs.

Everything else is near zero. The numbers are typical activations on those tokens in
training text (see the notes in the comments). This is a token-level rule: it only reads
the current token and the one before it, so it cannot follow the much larger, context
dependent swings in the tails.
"""

from collections.abc import Mapping

READS: tuple[str, ...] = ()

KEY_COLON = '":'  # closes a JSON key, e.g. {"name":
VALUE_QUOTE = {'"', ' "'}  # opens a JSON string value, right after KEY_COLON
EQUALS = {"=", " =", "==", " ==", ")="}
COLONS = {":", " :", "："}
PLUS = {"+", " +"}


def step(carry, prefix, upstream: Mapping):
    tok = prefix.token_strings[-1]
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same_doc else ""
    if tok == KEY_COLON:
        # mean about -9 after "name" (tool-call name key), about -2 after other keys
        value = -9.0 if prev == "name" else -2.2
    elif tok in VALUE_QUOTE and prev == KEY_COLON:
        value = -1.1
    elif tok in EQUALS:
        value = -1.0
    elif tok in COLONS or tok in PLUS:
        value = -0.7
    else:
        value = 0.0
    return carry, value

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:1428 (layer 15 MLP write).

What it is: a signed, mostly small (std 0.6) activation that is large in two
kinds of place, and which a short list of token patterns can only partly
predict:

- Strongly negative on a type name in a code declaration, most of all right
  after an access modifier ("private int", "public static void", "private
  String"). Other type names (int, String, double, bool, void...) are
  moderately negative.
- Strongly negative on the "of" of a knowledge-graph relation after "place"
  ("place of birth/death") or "country" ("country of citizenship/origin").
- Positive on the list/graph separators "|", "—" and "->", and on "of" after
  quantifiers ("couple of", "total of", "none of").

Everything else is predicted as 0 (the component's mean is about -0.05).
Predictions use only the current token and the one before it, within the
same document.
"""

READS = ()

TYPE_NAMES = {"int", "long", "short", "byte", "char", "float", "double",
              "bool", "boolean", "String", "string", "Object", "void"}
MODIFIERS = {"public", "private", "protected", "static", "final"}
RELATION_NOUNS = {"place": -9.7, "country": -6.3, "language": -3.0}
QUANTIFIERS = {"couple", "total", "rest", "none", "several", "handful"}
SEPARATORS = {"|": 0.6, "—": 1.2, "->": 1.2}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1].strip()
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2].strip() if same_doc else ""
    if cur in TYPE_NAMES:
        v = -5.8 if prev in MODIFIERS else -1.9
    elif cur == "of" and prev in RELATION_NOUNS:
        v = RELATION_NOUNS[prev]
    elif cur == "of" and prev in QUANTIFIERS:
        v = 0.9
    elif cur == "name":
        v = -3.1 if prev == '{"' else -1.3
    elif cur == "place":
        v = -1.9
    elif cur in SEPARATORS:
        v = SEPARATORS[cur]
    else:
        v = 0.0
    return carry, v

"""Reason connectives that open a causal clause (L15 MLP down_proj, component 1429).

The component writes a small signal that is positive on the word that opens
a reason clause: "because", "since" used causally (", since it ..."), and
their equivalents in other languages (porque, weil, karena, 因为, поскольку).
Its value is largest when the connective follows a comma or parenthesis.
It is near zero for dismissive "just because", for temporal "since" (has
been ..., since 2010), and for ordinary words. It is also weakly positive on
"as" opening a clause after a comma, and on relative words (which, who,
where, whose, when). Commas are slightly negative.
"""

READS = ()

BECAUSE = {
    "because", "porque", "weil", "karena", "perché", "pois", "поскольку",
    "ведь", "因为", "因為",
}
SINCE = {"since", "denn", "由于", "由於", "потому"}
RELATIVE = {"which", "who", "where", "whose", "whom", "который", "которые"}
OPENERS = {",", "，", "(", ")"}  # a comma or parenthesis before the connective
DISMISSIVE = {"just", "simply", "only", "not", "be"}  # "just because", "not because"
TEMPORAL = {"has", "have", "had", "ever", "been", "years", "year", "time"}  # "since 2010"
COMMA = {",": -0.13, "，": -0.25}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = _word(prefix.token_strings[-2]) if same_doc else ""
    after_opener = prev in OPENERS
    if word in BECAUSE:
        value = 0.0 if prev in DISMISSIVE else 2.0
    elif word in SINCE:
        if prev in TEMPORAL:
            value = 0.0
        else:
            value = 2.0 if after_opener else 0.8
    elif word == "as":
        value = 1.7 if after_opener else 0.1
    elif word in RELATIVE or word == "when":
        value = 0.35 * (1.5 if after_opener else 1.0)
    elif word in COMMA:
        value = COMMA[word]
    else:
        value = 0.0
    return carry, value

"""Layer 15 MLP down-projection, component 1431: a diffuse, mostly unpredictable signal.

What it does: the component's activation is spread thinly over almost every
token (std about 0.34), with no concept that explains more than a sliver of it.
This program predicts only the small, consistent per-kind averages seen in
training text:

- the first token of each document: 0 (the component is near silent there);
- Han (Chinese/Japanese) characters: slightly negative;
- ordinary words: slightly negative;
- LaTeX and math symbols (backslash, $, ^, _): slightly positive;
- everything else (digits, punctuation, spaces, newlines): about 0.

Why: the component's largest values come from academic/mathematical prose
(e.g. "we show [that]", "which [represents]") and its most negative from
heading and instruction openers ("Theorem 3.1.", "Let", "Define", "Find").
Those contexts are rare; across all tokens, no simple rule tracks the
activation. Token identity explains under 1% of its variance on held-out text.
"""
import re
from collections.abc import Mapping

READS: tuple[str, ...] = ()

HAN = re.compile(r"[一-鿿㐀-䶿]")
WORD = re.compile(r" ?[A-Za-z]+")
LATEX = re.compile(r"[\\$^_]")

MEAN = {"han": -0.05, "word": -0.03, "latex": 0.03, "other": 0.0}


def kind(text: str) -> str:
    if HAN.search(text):
        return "han"
    if WORD.fullmatch(text):
        return "word"
    if LATEX.search(text):
        return "latex"
    return "other"


def step(carry, prefix, upstream: Mapping):
    # A document's first token: the component is silent there.
    if prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, 0.0
    return carry, MEAN[kind(prefix.token_strings[-1])]

"""Layer 15 MLP down_proj, component 1456: a diffuse read with no readable trigger.

Its activation is (hidden . V) * |U| over the MLP's 6144 hidden units. Its input weight
is 39% on unit 1456 itself and 61% spread over the other units, and its activation
correlates 0.35 with unit 1456's own value, but no single token, word class or position
picks it out: token identity alone explains about 1% of its variance, and simple
surface features add nothing. Measured on sampled text, its values are about zero at a
document's first token, mildly negative over the next few tokens, and otherwise a small
class-dependent offset: slightly positive after common English words and commas, slightly
negative after other words. The class means below are the only systematic part found;
they explain under 0.5% of its variance on eval. The component is almost inert in the
model: switching it off barely changes next-token predictions.
"""
from wordfreq import top_n_list

READS = ()

COMMON = frozenset(w.lower() for w in top_n_list("en", 150))
MEAN_BY_CLASS = {
    "common": 0.027,  # frequent English words such as "of", "the", "and"
    "digit": 0.010,
    "mixed": -0.041,  # letters mixed with other characters
    "word": -0.021,  # other alphabetic words
    "punct": 0.003,  # punctuation, including commas
    "space": -0.005,  # whitespace-only tokens
}


def word_class(text):
    word = text.strip()
    if not word:
        return "space"
    if word.isdigit():
        return "digit"
    if all(not ch.isalnum() for ch in word):
        return "punct"
    if word.lower() in COMMON:
        return "common"
    if word.isalpha():
        return "word"
    return "mixed"


def step(carry, prefix, upstream):
    # carry: (document id, position within the document) of the previous token.
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        pos = 0
    else:
        pos = carry[1] + 1
    if pos == 0:
        value = 0.0  # a document's first token: the component is silent
    elif pos < 5:
        value = -0.05  # the next few tokens dip negative
    else:
        value = MEAN_BY_CLASS[word_class(prefix.token_strings[-1])]
    return (doc, pos), value

"""Edge-case values: the component fires where the text sets, tests or returns a
trivial value -- a literal 0 or 1 that is the value being compared or assigned
(`n == 0`, `x = 1`, `f(0) = 0`, `0^0 = 1`, `n is 0`), the word `return`, and words
like `empty`, `zero`, `null`, `trivial` or `default`. It is weaker on the operators
that set up such a test (`==`, `!=`, `||`, `??`, `=`). Everywhere else it predicts
a near-zero value. The values are the average activations of these groups on
training text, so the program is a calibrated group lookup, not a fit to the bulk
of the activation, which is diffuse and not explained here."""

READS = ()

# Tokens that make a 0 or 1 a comparison or an assignment target.
SETTERS = {"=", "==", "===", "!=", "≠", ")=", "is", "<", ">", "<=", ">="}
OPENERS = {"(", "[", "{"}
ZERO_ONE = {"0", "1"}
# Words for a trivial, empty or missing value.
TRIVIAL_WORDS = {
    "empty", "zero", "trivial", "null", "nil", "none", "undefined", "default",
    "defaults", "nan", "Empty", "Zero", "Null", "NULL", "None",
}
# Operators that open a check on such a value.
CHECK_OPS = {"==", "!=", "≠", "||", "??", "="}


def previous_word(prefix, back=6):
    """The nearest token before the newest one that is not a space, in the same document."""
    last = len(prefix.token_strings) - 1
    for i in range(last - 1, max(-1, last - back), -1):
        if prefix.document_ids[i] != prefix.document_ids[last]:
            return ""
        text = prefix.token_strings[i].strip()
        if text:
            return text
    return ""


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    before = previous_word(prefix) if len(prefix.token_ids) > 1 else ""
    if word in ZERO_ONE and before in SETTERS:
        value = 0.75  # `== 0`, `= 1`, `is 0`
    elif word in ZERO_ONE and before in OPENERS:
        value = 0.2  # `f(0)`, `[0]`
    elif word == "return" or word in TRIVIAL_WORDS:
        value = 0.8
    elif word in CHECK_OPS:
        value = 0.15
    else:
        value = 0.03
    return carry, value

"""Layer 15 MLP unit 1466 (down_proj component 1466) goes negative inside names and terms.

This component reads almost only MLP hidden unit 1466 of layer 15, so its activation is that
unit's value. The unit is near zero on most text, and strongly negative on the later words of
multi-word names and technical terms. This program adds up four readable effects:

- a capitalized word that continues a capitalized name ("Council" in "European Research
  Council", "Health" in "World Health Organization");
- "of" or "for" inside a name ("Court of", "Museum of");
- the head word of an organization or institution ("League", "Agency", "Union");
- the word that completes a known multi-word term in WordNet ("gross domestic product",
  "public relations"), and, more weakly, a common noun after another word.

It explains only about 2% of the variance: the largest values depend on how familiar a
phrase is to the model, which a short program cannot see.
"""

import wordnet

READS = ()

CONNECTORS = ("of", "for")
MAX_LOOKBACK = 12


def _is_name_word(text):
    """A capitalized word, the kind that makes up a name."""
    return text.isalpha() and text.isascii() and text[:1].isupper()


def _is_term_end(texts):
    """Whether the last 2 to 4 words of the text end in a multi-word term WordNet lists."""
    words = "".join(texts).split()
    for k in (4, 3, 2):
        if len(words) >= k and wordnet.parts_of_speech(" ".join(words[-k:]).lower()):
            return True
    return False


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    docs = prefix.document_ids
    t = len(toks) - 1
    cur = toks[t].strip()
    # the same document's tokens before this one, nearest last
    start = t
    while start > 0 and docs[start - 1] == docs[t] and t - start < MAX_LOOKBACK:
        start -= 1
    before = [tok.strip() for tok in toks[start:t]]
    prev = before[-1] if before else ""
    value = -0.02
    if _is_name_word(cur) and _is_name_word(prev):
        value -= 0.58
    if cur in CONNECTORS and _is_name_word(prev):
        value -= 0.34
    if cur.isalpha():
        word = cur.lower()
        if wordnet.is_a(word, "organization") or wordnet.is_a(word, "institution"):
            value -= 0.24
        if prev.isalpha() and "noun" in wordnet.parts_of_speech(word):
            value -= 0.09
        if _is_term_end(toks[start : t + 1]):
            value -= 1.04
    return carry, float(value)
